# DIMENSIONS
level = 1
D = [D1, D2]
I_max = len(D[0][0])
J_max = len(D[0])
group = len(D)
n = 6 * (4 ** (level - 1))
N = I_max * J_max
N_hexx = I_max * J_max * n

# Noise Input Manipulation
TOT_hexx2 = expand_XS_hexx_2D(group, J_max, I_max, TOT, level)

#######################################################################################################
data_file = "iteration_info.txt"

results = []

with open(data_file, 'r') as f:
    for line in f:
        # --- Extract iteration, num_source, frequency, and loc_conv ---
        iteration = int(re.search(r"Iteration:\s*(\d+)", line).group(1))
        num_source = int(re.search(r"num_source:\s*(\d+)", line).group(1))
        frequency = float(re.search(r"frequency:\s*([0-9.eE+-]+)", line).group(1))

        # Extract loc_conv as a list of integers
        loc_section = re.search(r"loc\s*=\s*\[(.*?)\]", line)
        loc = [int(x) for x in loc_section.group(1).split(",")] if loc_section else []
        loc_conv_section = re.search(r"loc_conv\s*=\s*\[(.*?)\]", line)
        loc_conv = [int(x) for x in loc_conv_section.group(1).split(",")] if loc_conv_section else []

        # --- Extract Real and Imaginary magnitudes ---
        real_section = re.search(r"Real magnitude\s*=\s*\[(.*?)\]", line)
        imag_section = re.search(r"Imaginary magnitude\s*=\s*\[(.*?)\]", line)

        def parse_floats(section):
            if not section:
                return []
            text = section.group(1)
            # Match numbers inside np.float64(...) or plain numeric tokens
            matches = re.findall(
                r"np\.float64\(([-+]?\d*\.\d+(?:[eE][-+]?\d+)?|\d+)\)|([-+]?\d*\.\d+(?:[eE][-+]?\d+)?|\d+)",
                text,
            )
            # Flatten tuples and convert to floats
            return [float(a or b) for a, b in matches]

        real_vals = parse_floats(real_section)
        imag_vals = parse_floats(imag_section)

        # --- Combine real + imag and make complex numbers ---
        combined = [r + i for r, i in zip(real_vals, imag_vals)]
        complex_vals = [r + 1j * i for r, i in zip(real_vals, imag_vals)]

        # Store result
        results.append({
            "iteration": iteration,
            "num_source": num_source,
            "frequency": frequency,
            "loc": loc,
            "loc_conv": loc_conv,
            "real": real_vals,
            "imag": imag_vals,
            "sum": combined,
            "complex": complex_vals,
        })

